(function(root){
'use strict';
function determinant(a){return a[0][0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1])-a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0])+a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0])}
function statistics(c,labels){const voxelMM3=Math.abs(determinant(c.affine)),result=labels.map(l=>({label:l.value,name:l.name,voxels:0,volumeML:0,occupiedKSlices:0,internalEmptyKSlices:0})),map=new Map(result.map(r=>[r.label,r])),counts=new Map(labels.map(l=>[l.value,new Uint32Array(c.dims[2])])),plane=c.dims[0]*c.dims[1];let unknown=0;for(let i=0;i<c.mask.length;i++){const value=c.mask[i];if(!value)continue;const row=map.get(value);if(!row){unknown++;continue}row.voxels++;counts.get(value)[Math.floor(i/plane)]++}for(const row of result){row.volumeML=c.geometry==='unknown'?null:row.voxels*voxelMM3/1000;const slices=counts.get(row.label),occupied=[];slices.forEach((n,i)=>{if(n)occupied.push(i)});row.occupiedKSlices=occupied.length;if(occupied.length)row.internalEmptyKSlices=occupied.at(-1)-occupied[0]+1-occupied.length}return {labels:result,unknownVoxels:unknown,voxelMM3,geometryKnown:c.geometry!=='unknown',dimensions:c.dims}}
function compare(c,r,labels){if(c.dims.some((n,i)=>n!==r.dims[i]))throw Error('Reference mask shape does not match');if(c.affine.some((row,i)=>row.some((v,j)=>Math.abs(v-r.affine[i][j])>1e-4)))throw Error('Reference mask affine does not match; do not compare unregistered masks');const allowed=new Set([0,...labels.map(l=>l.value)]);for(const x of r.data)if(!Number.isInteger(x)||!allowed.has(x))throw Error('Reference contains non-integer or unknown label values');return labels.map(l=>{let a=0,b=0,intersection=0;for(let i=0;i<c.mask.length;i++){const aa=c.mask[i]===l.value,bb=r.data[i]===l.value;if(aa)a++;if(bb)b++;if(aa&&bb)intersection++}return {label:l.value,name:l.name,primaryVoxels:a,referenceVoxels:b,dice:a+b?2*intersection/(a+b):null,iou:a+b-intersection?intersection/(a+b-intersection):null,bothEmpty:a+b===0}})}
function releaseErrors(project,c){const e=[];const release=project.release||{};for(const field of ['version','steward','licenseName','licenseText','sourceReference','authorizationReference','deidentificationMethod','intendedUse','limitations'])if(!String(release[field]||'').trim())e.push('Release field required: '+field);if(release.commercialAuthorized!==true)e.push('Dataset commercial authorization not confirmed');for(const field of ['training','redistribution','commercial','deidentified'])if(c.rights?.[field]!==true)e.push(c.id+': '+field+' permission/check missing');if(!c.rights?.reference?.trim())e.push(c.id+': authorization reference missing');if(!c.reviewer?.trim())e.push(c.id+': primary reviewer missing');if(!c.releaseApproval?.reviewer||c.releaseApproval.reviewer===c.reviewer||c.releaseApproval.revision!==(c.annotationRevision||0))e.push(c.id+': current independent review required');if(c.status!=='reviewed')e.push(c.id+': case not reviewed');return e}
const api={statistics,compare,releaseErrors};root.MedQuality=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
